"""
noVNC 实时登录 API。

POST /api/live-login/start          启动 noVNC 登录会话
POST /api/live-login/{id}/confirm   确认登录完成
POST /api/live-login/{id}/stop      取消/停止会话
GET  /api/live-login/{id}/status    查询会话状态
"""

from __future__ import annotations

import base64
import logging
from typing import Optional

from fastapi import APIRouter, Header, HTTPException
from pydantic import BaseModel

from services.live_login_service import (
    LiveSession,
    confirm_login,
    get_session,
    get_session_time_remaining,
    start_live_session,
    stop_live_session,
)
from services.platform_session_store import build_browser_session_key
from services.supabase_client import (
    get_platform_account,
    update_platform_account,
    validate_supabase_user,
)

router = APIRouter(prefix="/api/live-login", tags=["live-login"])
logger = logging.getLogger(__name__)


# ── 请求/响应模型 ────────────────────────────────────────────────

class StartRequest(BaseModel):
    account_id: str
    login_url: str | None = None


class StartResponse(BaseModel):
    session_id: str
    ws_port: int
    vnc_token: str
    ws_url: str
    login_url: str
    timeout_seconds: int


class ConfirmResponse(BaseModel):
    success: bool
    is_logged_in: bool
    message: str
    workspace_saved: bool = False
    db_saved: bool = False
    persistence_detail: str = ""


class StatusResponse(BaseModel):
    session_id: str
    active: bool
    time_remaining: float | None = None
    ws_port: int | None = None
    vnc_token: str | None = None


# ── 辅助 ─────────────────────────────────────────────────────────

def _read_bearer(authorization: Optional[str]) -> str:
    if not authorization:
        return ""
    parts = authorization.split(" ", 1)
    if len(parts) == 2 and parts[0].lower() == "bearer":
        return parts[1].strip()
    return authorization.strip()


async def _validate_request_user(auth_token: str):
    if not auth_token:
        raise HTTPException(status_code=401, detail="缺少 Supabase 用户令牌")
    try:
        return await validate_supabase_user(auth_token)
    except ValueError as exc:
        raise HTTPException(status_code=401, detail=str(exc)) from exc
    except PermissionError as exc:
        raise HTTPException(status_code=403, detail=str(exc)) from exc


# ── 路由 ─────────────────────────────────────────────────────────

@router.post("/start", response_model=StartResponse)
async def api_start_live_login(
    body: StartRequest,
    authorization: Optional[str] = Header(None),
):
    """启动 noVNC 实时登录会话。"""
    auth_token = _read_bearer(authorization)
    user_info = await _validate_request_user(auth_token)
    tenant_id = user_info["tenant_id"]

    account = get_platform_account(body.account_id, tenant_id, auth_token=auth_token)
    if not account:
        raise HTTPException(status_code=404, detail="平台账号不存在")

    browser_session_key = account.get("browser_session_key") or build_browser_session_key(
        tenant_id, account["platform"], body.account_id,
    )

    try:
        session = await start_live_session(
            account_id=body.account_id,
            tenant_id=tenant_id,
            platform=account["platform"],
            browser_session_key=browser_session_key,
            login_url=body.login_url,
        )
    except RuntimeError as e:
        status = 429 if "通道已满" in str(e) else 409
        raise HTTPException(status_code=status, detail=str(e)) from e

    # 更新账号状态
    update_platform_account(
        body.account_id,
        tenant_id,
        {
            "status": "verifying",
            "login_state": "LIVE_SESSION_ACTIVE",
            "browser_session_key": browser_session_key,
        },
        auth_token=auth_token,
    )

    from services.live_login_service import SESSION_TIMEOUT
    ws_url = f"/novnc/{session.ws_port}/vnc.html?autoconnect=true&resize=scale&path=novnc/{session.ws_port}/websockify"
    return StartResponse(
        session_id=session.session_id,
        ws_port=session.ws_port,
        vnc_token=session.vnc_token,
        ws_url=ws_url,
        login_url=session.login_url,
        timeout_seconds=SESSION_TIMEOUT,
    )


@router.post("/{session_id}/confirm", response_model=ConfirmResponse)
async def api_confirm_live_login(
    session_id: str,
    authorization: Optional[str] = Header(None),
):
    """用户确认登录完成，提取并持久化 cookies。"""
    auth_token = _read_bearer(authorization)
    user_info = await _validate_request_user(auth_token)
    tenant_id = user_info["tenant_id"]

    session = get_session(session_id)
    if not session:
        raise HTTPException(status_code=404, detail="会话不存在或已关闭")
    if session.tenant_id != tenant_id:
        raise HTTPException(status_code=403, detail="无权访问该登录会话")

    async def supabase_updater(account_id: str, encrypted: bytes, login_state: str):
        try:
            encoded = base64.b64encode(encrypted).decode()
            update_platform_account(
                account_id,
                tenant_id,
                {
                    "encrypted_session_state": encoded,
                    "login_state": login_state,
                    "status": "active",
                    "is_connected": True,
                },
                auth_token=auth_token,
            )
            saved_row = get_platform_account(account_id, tenant_id, auth_token=auth_token) or {}
            db_saved = (
                bool(saved_row.get("encrypted_session_state"))
                and saved_row.get("login_state") == "LOGGED_IN"
                and saved_row.get("status") == "active"
            )
            detail = (
                "数据库字段已回读确认"
                if db_saved
                else "数据库回读失败：encrypted_session_state/login_state/status 未全部生效"
            )
            if not db_saved:
                logger.warning("live_login DB 持久化校验失败: account_id=%s", account_id)
            return {"saved": db_saved, "detail": detail}
        except Exception as exc:
            logger.exception("live_login DB 持久化异常: account_id=%s", account_id)
            return {"saved": False, "detail": f"数据库持久化异常：{exc}"}

    try:
        result = await confirm_login(session_id, supabase_updater=supabase_updater)
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"提取登录信息失败: {e}") from e

    workspace_saved = bool(result.get("persistence", {}).get("workspace_saved", False))
    db_saved = bool(result.get("persistence", {}).get("db_saved", False))
    persistence_detail = " | ".join(
        part for part in [
            str(result.get("persistence", {}).get("workspace_detail", "")).strip(),
            str(result.get("persistence", {}).get("db_detail", "")).strip(),
        ] if part
    )

    if result["is_logged_in"] and workspace_saved and db_saved:
        return ConfirmResponse(
            success=True,
            is_logged_in=True,
            message="登录成功，会话已保存",
            workspace_saved=True,
            db_saved=True,
            persistence_detail=persistence_detail,
        )
    if persistence_detail:
        if not workspace_saved and not db_saved:
            message = "登录态已识别，但工作区和数据库持久化都失败"
        elif not db_saved:
            message = "登录态已识别，但数据库持久化失败"
        elif not workspace_saved:
            message = "登录态已识别，但工作区持久化失败"
        else:
            message = "登录态未通过持久化校验，请确认登录后重试"
    else:
        message = "未检测到有效登录状态，请继续在远程桌面中完成登录"

    return ConfirmResponse(
        success=False,
        is_logged_in=False,
        message=message,
        workspace_saved=workspace_saved,
        db_saved=db_saved,
        persistence_detail=persistence_detail,
    )


@router.post("/{session_id}/stop")
async def api_stop_live_login(
    session_id: str,
    authorization: Optional[str] = Header(None),
):
    """取消/停止 noVNC 会话。"""
    auth_token = _read_bearer(authorization)
    user_info = await _validate_request_user(auth_token)
    tenant_id = user_info["tenant_id"]

    session = get_session(session_id)
    if session:
        if session.tenant_id != tenant_id:
            raise HTTPException(status_code=403, detail="无权访问该登录会话")
        update_platform_account(
            session.account_id,
            tenant_id,
            {
                "status": "needsLogin",
                "login_state": "NOT_BOUND",
            },
            auth_token=auth_token,
        )
    await stop_live_session(session_id)
    return {"status": "stopped"}


@router.get("/{session_id}/status", response_model=StatusResponse)
async def api_live_login_status(
    session_id: str,
    authorization: Optional[str] = Header(None),
):
    """查询 noVNC 会话状态。"""
    auth_token = _read_bearer(authorization)
    user_info = await _validate_request_user(auth_token)
    tenant_id = user_info["tenant_id"]

    session = get_session(session_id)
    if not session:
        return StatusResponse(session_id=session_id, active=False)
    if session.tenant_id != tenant_id:
        raise HTTPException(status_code=403, detail="无权访问该登录会话")

    return StatusResponse(
        session_id=session_id,
        active=True,
        time_remaining=get_session_time_remaining(session_id),
        ws_port=session.ws_port,
        vnc_token=session.vnc_token,
    )

"""
平台账号与绑定会话 API。
"""

from __future__ import annotations

from datetime import datetime, timezone
from typing import Any, Optional

from fastapi import APIRouter, Header, HTTPException
from pydantic import BaseModel, Field
from sse_starlette.sse import EventSourceResponse

from services.platform_binding_service import (
    ensure_verify_session_ready,
    get_binding_session_snapshot,
    is_binding_session_running,
    refresh_qr_session,
    start_unbind_session,
    start_verify_session,
    stream_binding_events,
)
from services.platform_catalog import get_platform_catalog_item
from services.platform_session_store import build_browser_session_key, clear_session_artifacts
from services.supabase_client import (
    attach_latest_binding_session,
    create_platform_account,
    delete_platform_account,
    get_binding_session,
    get_platform_account,
    list_binding_sessions,
    list_platform_accounts,
    update_binding_session,
    update_platform_account,
    validate_supabase_user,
)

router = APIRouter(tags=["platform-accounts"])


def _now_iso() -> str:
    return datetime.now(timezone.utc).isoformat()


def _repair_orphaned_binding_session(
    item: dict[str, Any],
    tenant_id: str,
    auth_token: str,
) -> dict[str, Any]:
    latest_session = item.get("latest_binding_session") or {}
    session_id = str(latest_session.get("id") or "").strip()
    if latest_session.get("status") != "running" or not session_id:
        return item
    if is_binding_session_running(session_id):
        return item

    reason = "后端任务已中断，系统已自动修复状态，请按需重新发起验证"
    repaired_session = update_binding_session(
        session_id,
        tenant_id,
        {
            "status": "failed",
            "error_message": reason,
            "updated_at": _now_iso(),
        },
        auth_token=auth_token,
    )

    has_persisted_session = bool(item.get("encrypted_session_state"))
    if has_persisted_session:
        account_patch = {
            "status": "active",
            "is_connected": True,
            "login_state": "LOGGED_IN",
            "last_error": None,
        }
    else:
        account_patch = {
            "status": "needsLogin",
            "is_connected": False,
            "last_error": reason,
        }

    repaired_account = update_platform_account(
        item["id"],
        tenant_id,
        account_patch,
        auth_token=auth_token,
    )
    merged = {**item, **repaired_account}
    merged["latest_binding_session"] = repaired_session
    return merged


def _repair_interrupted_verify_session(
    *,
    account: dict[str, Any],
    binding_session: dict[str, Any],
    tenant_id: str,
    auth_token: str,
) -> dict[str, Any]:
    reason = "上一次验证任务已中断，系统已自动释放占用，可重新发起验证"
    repaired_session = update_binding_session(
        binding_session["id"],
        tenant_id,
        {
            "status": "failed",
            "error_message": reason,
            "updated_at": _now_iso(),
        },
        auth_token=auth_token,
    )

    if account.get("encrypted_session_state"):
        update_platform_account(
            account["id"],
            tenant_id,
            {
                "status": "active",
                "is_connected": True,
                "login_state": "LOGGED_IN",
                "last_error": None,
            },
            auth_token=auth_token,
        )
    else:
        update_platform_account(
            account["id"],
            tenant_id,
            {
                "status": "expired",
                "is_connected": False,
                "last_error": reason,
            },
            auth_token=auth_token,
        )
    return repaired_session


def _find_reusable_verify_session(
    *,
    account: dict[str, Any],
    tenant_id: str,
    auth_token: str,
) -> Optional[dict[str, Any]]:
    sessions = list_binding_sessions(tenant_id, account_id=account["id"], auth_token=auth_token)
    for session in sessions:
        if session.get("action") != "verify" or session.get("status") != "running":
            continue
        session_id = str(session.get("id") or "").strip()
        if not session_id:
            continue
        if is_binding_session_running(session_id):
            return session
        _repair_interrupted_verify_session(
            account=account,
            binding_session=session,
            tenant_id=tenant_id,
            auth_token=auth_token,
        )
        return None
    return None


def _read_bearer(authorization: Optional[str]) -> str:
    if not authorization:
        return ""
    parts = authorization.split(" ", 1)
    if len(parts) == 2 and parts[0].lower() == "bearer":
        return parts[1].strip()
    return authorization.strip()


async def _validate_request_user(auth_token: str):
    if not auth_token:
        raise HTTPException(status_code=401, detail="缺少 Supabase 用户令牌")
    try:
        return await validate_supabase_user(auth_token)
    except ValueError as exc:
        raise HTTPException(status_code=401, detail=str(exc)) from exc
    except PermissionError as exc:
        raise HTTPException(status_code=403, detail=str(exc)) from exc


class PlatformAccountCreateRequest(BaseModel):
    platform: str
    name: str
    account_name: str = ""
    platform_url: str = ""
    supabase_auth_token: str = ""




class PlatformAccountActionRequest(BaseModel):
    supabase_auth_token: str = ""


@router.get("/api/platform-accounts")
async def get_platform_accounts(
    authorization: Optional[str] = Header(default=None),
):
    auth_token = _read_bearer(authorization)
    user = await _validate_request_user(auth_token)
    accounts = list_platform_accounts(user["tenant_id"], auth_token=auth_token)
    items = attach_latest_binding_session(accounts, user["tenant_id"], auth_token=auth_token)
    repaired_items = [
        _repair_orphaned_binding_session(item, user["tenant_id"], auth_token)
        for item in items
    ]
    return {"items": repaired_items}


@router.post("/api/platform-accounts")
async def create_platform_account_route(req: PlatformAccountCreateRequest):
    user = await _validate_request_user(req.supabase_auth_token)
    catalog_item = get_platform_catalog_item(req.platform)
    account = create_platform_account(
        {
            "tenant_id": user["tenant_id"],
            "platform": req.platform,
            "name": req.name.strip(),
            "account_name": req.account_name.strip() or None,
            "platform_url": req.platform_url.strip() or catalog_item["enterprise_url"],
            "login_method": catalog_item["recommended_login_method"],
            "browser_session_key": "",
            "login_state": "NOT_BOUND",
            "login_identifier_masked": None,
            "last_error": None,
            "last_bind_task_id": None,
            "last_unbind_task_id": None,
            "config": {
                "platform_name": catalog_item["name"],
                "supported_login_methods": catalog_item["supported_login_methods"],
            },
            "is_connected": False,
            "status": "needsLogin",
        },
        auth_token=req.supabase_auth_token,
    )
    browser_session_key = build_browser_session_key(user["tenant_id"], req.platform, account["id"])
    account = update_platform_account(
        account["id"],
        user["tenant_id"],
        {"browser_session_key": browser_session_key},
        auth_token=req.supabase_auth_token,
    )
    return {"item": account}


@router.get("/api/platform-binding-sessions/{session_id}")
