                                    className="text-red-600 focus:text-red-600 dark:text-red-400"
                                    onClick={() => handleAction('unbind', account.id)}
                                    disabled={actionPendingAccountId === account.id}
                                  >
                                    <Unplug className="mr-2 h-4 w-4"/>解绑账号
                                  </DropdownMenuItem>
